DROP TABLE IF EXISTS `airtel_payment_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `airtel_payment_request` (
  `request_id` varchar(225) NOT NULL,
  `kazi_transaction_id` varchar(225) NOT NULL,
  `amount` float NOT NULL,
  `phone` varchar(20) NOT NULL,
  `tra_id` varchar(200) NOT NULL,
  `created_date` datetime NOT NULL,
  PRIMARY KEY (`request_id`),
  KEY `kazi_transaction_id` (`kazi_transaction_id`),
  CONSTRAINT `airtel_payment_request_ibfk_1` FOREIGN KEY (`kazi_transaction_id`) REFERENCES `inbound_Transactions` (`transaction_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

