DROP TABLE IF EXISTS `wallet_response`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallet_response` (
  `wallet_response_id` varchar(225) NOT NULL,
  `request_id` varchar(225) NOT NULL,
  `input_OriginalConversationID` varchar(100) NOT NULL,
  `input_TransactionID` varchar(100) NOT NULL,
  `input_ResultCode` varchar(100) NOT NULL,
  `input_ResultDesc` varchar(225) NOT NULL,
  `input_ThirdPartyConversationID` varchar(225) NOT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`wallet_response_id`),
  KEY `request_id` (`request_id`),
  CONSTRAINT `wallet_response_ibfk_1` FOREIGN KEY (`request_id`) REFERENCES `voda_requests_push` (`request_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

